sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var ageString = api.item.value.worker._reference.age.displayValue ? ` (${api.item.value.worker._reference.age.displayValue})` : "";
	return `${api.item.value.worker.displayValue}${ageString}`;
}
